package com.kafka.backend.shareddesk;
import com.kafka.backend.shareddesk.storage.*;
import org.springframework.stereotype.Service;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import static com.kafka.backend.shareddesk.DeskService.*;

@Service
public class DeskFiles {
 final DeskService s; final ObjectStorage storage;
 public DeskFiles(DeskService service,ObjectStorage storage){this.s=service;this.storage=storage;}
 Map<String,Object> file(UUID o,UUID id){s.active(o,id,"FILE");var rows=s.rows("select * from shared_desk_files where owner_id=? and item_id=?",o,id);if(rows.isEmpty())throw error(404,"NOT_FOUND","파일을 찾을 수 없습니다.");return rows.getFirst();}
 FilePolicy.Claim claim(Map<String,Object> f){return new FilePolicy.Claim(f.get("display_name").toString(),number(f.get("size_bytes")),f.get("sha256").toString(),f.get("claimed_mime").toString());}
 void quota(UUID o,long bytes){quota(o,bytes,null);}
 void quota(UUID o,long bytes,UUID replacing){
  quotaBytes(o,bytes);
  int active=replacing==null?s.db.queryForObject("select count(*) from shared_desk_files where owner_id=? and state in ('UPLOADING','VERIFYING')",Integer.class,o):s.db.queryForObject("select count(*) from shared_desk_files where owner_id=? and item_id<>? and state in ('UPLOADING','VERIFYING')",Integer.class,o,replacing);
  if(active>=3)throw error(429,"UPLOAD_LIMIT","파일은 동시에 3개까지 전송할 수 있습니다.");
 }
 void quotaBytes(UUID o,long bytes){
  long retained=s.db.queryForObject("select coalesce(sum(size_bytes),0) from shared_desk_files where owner_id=? and (state='READY' or (state='VERIFYING' and final_key is not null))",Long.class,o);
  long reserved=s.db.queryForObject("select coalesce(sum(size_bytes),0) from shared_desk_upload_reservations where owner_id=?",Long.class,o);
  if(retained+reserved+bytes>1073741824L)throw error(413,"QUOTA_EXCEEDED","개인 저장 한도 1 GiB를 초과합니다. 휴지통과 전송·검증 중 임시 파일도 포함됩니다.");
 }
 void reserve(UUID o,String key,long bytes,Instant uploadExpires){
  // signed() can reissue its fixed10min URL until uploadExpires. Cover the latest URL plus60s grace.
  // Even an expired reservation counts until the individual staging object has been deleted successfully.
  s.db.update("insert into shared_desk_upload_reservations(owner_id,staging_key,size_bytes,expires_at) values(?,?,?,?)",o,key,bytes,Timestamp.from(uploadExpires.plusSeconds(660)));
 }
 Map<String,Object> metadata(UUID id){var f=file(s.owner(),id);return Map.of("fileId",id,"ticketId",f.get("ticket_id"),"revision",s.raw(s.owner(),id).get("revision"),"expiresAt",instant(f.get("upload_expires_at")).toString());}
 Map<String,Object> signed(UUID id){UUID o=s.owner();var f=file(o,id);if(!"UPLOADING".equals(f.get("state")))throw error(409,"NOT_UPLOADING","전송 가능한 상태가 아닙니다.");if(instant(f.get("upload_expires_at")).isBefore(Instant.now()))throw error(410,"TICKET_EXPIRED","업로드 티켓을 다시 발급해주세요.");try{var ticket=storage.presignPut(o,f.get("staging_key").toString(),claim(f));var result=new LinkedHashMap<String,Object>(metadata(id));result.put("url",ticket.url().toString());result.put("method","PUT");result.put("requiredHeaders",ticket.requiredHeaders());return result;}catch(StorageFailure e){throw storageError(e);}}
 public Map<String,Object> create(Map<String,Object>b){s.fileGate();if(number(b.get("sizeBytes"))>FilePolicy.MAX_BYTES)throw error(413,"FILE_TOO_LARGE","파일은 100 MiB까지 전송할 수 있습니다.");FilePolicy.Claim claim;try{claim=new FilePolicy.Claim(text(b.get("displayName")),number(b.get("sizeBytes")),text(b.get("sha256")),text(b.get("claimedMime")));}catch(StorageFailure e){throw storageError(e);}var result=s.mutate("UPLOAD",b,()->{UUID o=s.owner(),id=UUID.randomUUID();quota(o,claim.sizeBytes());String staging=storage.newStagingKey(o);Instant expires=Instant.now().plusSeconds(600);s.db.update("insert into shared_desk_items(id,owner_id,kind,title,project_id) values(?,?,'FILE',?,?)",id,o,claim.displayName(),s.project(o,b.get("projectId")));s.db.update("insert into shared_desk_files(item_id,owner_id,display_name,size_bytes,sha256,claimed_mime,state,staging_key,ticket_id,upload_expires_at) values(?,?,?,?,?,?,'UPLOADING',?,?,?)",id,o,claim.displayName(),claim.sizeBytes(),claim.sha256(),claim.claimedMime(),staging,UUID.randomUUID(),Timestamp.from(expires));reserve(o,staging,claim.sizeBytes(),expires);s.change(o,id,"UPSERT");return metadata(id);});return signed(uuid(result.get("fileId")));}
 void cleanup(UUID o,Object key,Instant after){if(key==null)return;for(var f:s.rows("select size_bytes from shared_desk_files where owner_id=? and final_key=?",o,key.toString()))s.db.update("insert into shared_desk_upload_reservations(owner_id,staging_key,size_bytes,expires_at) values(?,?,?,?) on conflict(staging_key) do nothing",o,key.toString(),f.get("size_bytes"),Timestamp.from(after));s.db.update("insert into shared_desk_object_cleanup(owner_id,object_key,not_before) values(?,?,?) on conflict(object_key) do nothing",o,key.toString(),Timestamp.from(after));}
 public Map<String,Object> retry(UUID id,Map<String,Object>b){s.fileGate();s.mutate("RETRY/"+id,b,()->{UUID o=s.owner();var item=s.active(o,id,"FILE");s.revision(item,b);var f=file(o,id);String state=f.get("state").toString();if(state.equals("READY")||state.equals("VERIFYING")||state.equals("PURGED"))throw error(409,"INVALID_STATE","현재 파일 상태에서는 재전송할 수 없습니다.");if(state.equals("UPLOADING")&&instant(f.get("upload_expires_at")).isAfter(Instant.now()))throw error(409,"TICKET_ACTIVE","현재 전송을 취소한 뒤 다시 시도해주세요.");quota(o,number(f.get("size_bytes")),id);String staging=storage.newStagingKey(o);Instant expires=Instant.now().plusSeconds(600);cleanup(o,f.get("staging_key"),Instant.now().plusSeconds(660));cleanup(o,f.get("final_key"),Instant.now().plusSeconds(660));s.db.update("update shared_desk_files set state='UPLOADING',staging_key=?,final_key=null,ticket_id=?,upload_expires_at=?,failure_code=null,verification_operation=null,verification_started_at=null where owner_id=? and item_id=?",staging,UUID.randomUUID(),Timestamp.from(expires),o,id);reserve(o,staging,number(f.get("size_bytes")),expires);s.db.update("update shared_desk_items set revision=revision+1,updated_at=current_timestamp where owner_id=? and id=?",o,id);s.change(o,id,"UPSERT");return metadata(id);});return signed(id);}
 public Map<String,Object> cancel(UUID id,Map<String,Object>b){return s.mutate("CANCEL/"+id,b,()->{UUID o=s.owner();var item=s.active(o,id,"FILE");s.revision(item,b);var f=file(o,id);if("READY".equals(f.get("state"))||"PURGED".equals(f.get("state")))throw error(409,"INVALID_STATE","완료된 파일은 휴지통으로 이동해주세요.");cleanup(o,f.get("staging_key"),Instant.now().plusSeconds(660));cleanup(o,f.get("final_key"),Instant.now().plusSeconds(660));s.db.update("update shared_desk_files set state='CANCELLED',final_key=null where owner_id=? and item_id=?",o,id);s.db.update("update shared_desk_items set revision=revision+1,updated_at=current_timestamp where owner_id=? and id=?",o,id);s.change(o,id,"UPSERT");var result=s.view(s.raw(o,id),true);s.finishVerification(o,f.get("verification_operation"),result);return result;});}
 public Map<String,Object> complete(UUID id,Map<String,Object>b){s.fileGate();s.validOperation(b);UUID o=s.owner();String action="COMPLETE/"+id;var start=s.locked(o,()->{var previous=s.existing(o,action,b);if(previous!=null&&!"VERIFYING".equals(previous.get("status"))){if("CANCELLED".equals(previous.get("state")))throw error(409,"VERIFICATION_ABORTED","파일 전송을 취소했습니다.");return previous;}var item=s.active(o,id,"FILE");var f=file(o,id);if(previous!=null&&(!"VERIFYING".equals(f.get("state"))||!uuid(b.get("operationId")).equals(f.get("verification_operation"))||!uuid(b.get("ticketId")).equals(f.get("ticket_id"))))throw error(409,"VERIFICATION_ABORTED","기존 검증 작업이 취소되거나 전송 티켓이 바뀌었습니다.");if(previous==null){s.revision(item,b);if(!uuid(b.get("ticketId")).equals(f.get("ticket_id")))throw error(409,"TICKET_CHANGED","업로드 티켓이 변경되었습니다.");if(instant(f.get("upload_expires_at")).isBefore(Instant.now()))throw error(410,"TICKET_EXPIRED","업로드 티켓이 만료되었습니다.");if(!"UPLOADING".equals(f.get("state")))throw error(409,"INVALID_STATE","현재 상태에서 완료할 수 없습니다.");quotaBytes(o,number(f.get("size_bytes")));s.saveOperation(o,action,b,Map.of("status","VERIFYING"));}else if("VERIFYING".equals(f.get("state"))&&instant(f.get("verification_started_at")).isAfter(Instant.now().minusSeconds(300)))return Map.<String,Object>of("status","VERIFYING","id",id);
   cleanup(o,f.get("final_key"),Instant.now().plusSeconds(660));if(previous!=null)quotaBytes(o,0);String finalKey=storage.newFinalKey(o);s.db.update("update shared_desk_files set state='VERIFYING',final_key=?,verification_operation=?,verification_started_at=current_timestamp where owner_id=? and item_id=?",finalKey,uuid(b.get("operationId")),o,id);s.change(o,id,"UPSERT");var result=new LinkedHashMap<String,Object>();result.put("verify",true);result.put("finalKey",finalKey);result.put("stagingKey",f.get("staging_key"));result.put("claim",claim(f));return result;});
  if(!Boolean.TRUE.equals(start.get("verify")))return start;
  FilePolicy.Verified verified=null;StorageFailure.Code failure=null;try{verified=storage.promoteAndVerify(o,start.get("stagingKey").toString(),start.get("finalKey").toString(),(FilePolicy.Claim)start.get("claim"));}catch(StorageFailure e){failure=e.code();}
  final var proof=verified;final var fail=failure;
  return s.locked(o,()->{var f=file(o,id);if(!"VERIFYING".equals(f.get("state"))||!Objects.equals(f.get("final_key"),start.get("finalKey"))){cleanup(o,start.get("finalKey"),Instant.now().plusSeconds(660));throw error(409,"VERIFICATION_CHANGED","파일 전송 상태가 변경되었습니다.");}String state=fail==null?"READY":"FAILED";s.db.update("update shared_desk_files set state=?,detected_mime=?,verified_at=?,failure_code=? where owner_id=? and item_id=?",state,proof==null?null:proof.detectedMime(),proof==null?null:Timestamp.from(Instant.now()),fail==null?null:fail.name(),o,id);cleanup(o,f.get("staging_key"),Instant.now().plusSeconds(660));if(fail!=null)cleanup(o,f.get("final_key"),Instant.now().plusSeconds(660));s.db.update("update shared_desk_items set revision=revision+1,updated_at=current_timestamp where owner_id=? and id=?",o,id);s.change(o,id,"UPSERT");var result=s.view(s.raw(o,id),true);s.db.update("update shared_desk_operations set result=? where owner_id=? and operation_id=?",s.encode(result),o,uuid(b.get("operationId")));return result;});
 }
 public Map<String,Object> download(UUID id){s.fileGate();UUID o=s.owner();var f=file(o,id);if(!"READY".equals(f.get("state")))throw error(409,"FILE_NOT_READY","다운로드 준비가 되지 않았습니다.");try{var ticket=storage.presignGet(o,f.get("final_key").toString(),f.get("display_name").toString());s.db.update("update shared_desk_sync_heads set download_bytes_estimate=download_bytes_estimate+? where owner_id=?",f.get("size_bytes"),o);return Map.of("url",ticket.url().toString(),"expiresAt",ticket.expiresAt().toString(),"sha256",f.get("sha256"),"sizeBytes",f.get("size_bytes"),"displayName",f.get("display_name"));}catch(StorageFailure e){throw storageError(e);}}
 static DeskException storageError(StorageFailure e){return switch(e.code()){case DISABLED,UNAVAILABLE->error(503,"STORAGE_UNAVAILABLE","파일 저장소 연결을 확인해주세요.");case NOT_FOUND->error(422,"OBJECT_MISSING","업로드된 파일을 확인할 수 없습니다.");default->error(422,e.code().name(),"파일 형식·크기·무결성을 확인해주세요.");};}
}
